python -B - <<'PY'
import zipfile,json
z=zipfile.ZipFile('ArknightsGameData-master.zip')
for suffix in ['level_main_08-07.json','enemy_database.json']:
 p=next(n for n in z.namelist() if n.endswith(suffix) and 'zh_CN' in n)
 x=json.loads(z.read(p))
 if suffix.startswith('level'):
  print('OPTIONS',x['options'])
 else:
  for e in x['enemies']:
   if e['Key']=='enemy_1112_emppnt':
    print('ARTILLERY',json.dumps(e['Value'][0]['enemyData'],ensure_ascii=False))
p=next(n for n in z.namelist() if n.endswith('/character_table.json') and 'zh_CN' in n)
x=json.loads(z.read(p));print('ROADBLOCK', x['trap_020_roadblock']['phases'][0]['attributesKeyFrames'][0]['data'])
